  "parecer": "contradita",
  "tipo_efeito": "sem_efeito_local",
  "aspectos": {
    "entidade": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "A proposta identifica SUP_MOTOR; a alteração menciona esse identificador e a fonte local o define como o Fornecedor MotorTech.",
      "contexto_ids": []
    },
    "alvo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "A fonte local associa SUP_MOTOR à disponibilidade contratada e à restrição não antes de D18; o comunicado trata da nova disponibilidade contratada do mesmo SUP_MOTOR, correspondente ao alvo release_SUP_MOTOR.",
      "contexto_ids": []
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "O comunicado altera a disponibilidade contratada do fornecedor, atributo representado pela restrição local de disponibilidade não antes de uma data.",
      "contexto_ids": []
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "O comunicado especifica 25 dias corridos desde D0, e a fonte local também expressa a restrição em dias corridos.",
      "contexto_ids": []
    },
    "valor": {
      "estado": "insuficiente",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "O valor 25 é afirmado para o projeto PROJETO-B, mas o comunicado exclui expressamente sua aplicação ao ALFA-AMPLIADO. A fonte local registra D18 como restrição anterior, o que não confirma por si só o novo valor 25 para este projeto.",
      "contexto_ids": []
    },
    "condicoes": {
      "estado": "nao_aplicavel",
      "fonte_ids": [],
      "justificativa": "A proposta não declara condições de aplicação.",
      "contexto_ids": []
    },
    "escopo": {
      "estado": "contradito",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "O cadastro verificado vincula a proposta ao projeto ALFA-AMPLIADO, versão 1.0.0, com vigência prospectiva desde D0. O comunicado, porém, afirma que se aplica exclusivamente ao PROJETO-B e exclui expressamente o ALFA-AMPLIADO.",
      "contexto_ids": ["CONTEXTO.ESCOPO"]
    }
  },
  "fontes_examinadas": ["CHANGE.D02", "N.SUP_MOTOR"],
  "justificativa": "A magnitude de 25 dias aparece no comunicado, mas apenas para PROJETO-B. Como o próprio comunicado exclui sua aplicação ao projeto da proposta, não há efeito local sustentado para ALFA-AMPLIADO; o escopo proposto é contradito.",
  "suporte_ausente": [
    "Falta uma fonte que afirme a disponibilidade de 25 dias para SUP_MOTOR no ALFA-AMPLIADO; CHANGE.D02 limita esse valor a PROJETO-B e exclui expressamente sua aplicação ao ALFA-AMPLIADO."
  ],
  "contextos_examinados": ["CONTEXTO.ESCOPO"],
  "fundamentos_valor": {
    "valor": {
      "conhecimento": "exato",
      "valores": [25],
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "O comunicado afirma exatamente 25 dias corridos desde D0, mas declara que essa disponibilidade se aplica exclusivamente a PROJETO-B e exclui ALFA-AMPLIADO.",
      "aplicabilidade": "outro_objeto_ou_vigencia"
    }
  },
  "restricoes_escopo": [
    {
      "conhecimento": "exato",
      "valores": ["PROJETO-B"],
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "O comunicado restringe expressamente sua aplicação a PROJETO-B e exclui ALFA-AMPLIADO.",
      "campo": "projeto_id"
    }
  ]
}

